"""
配置加载模块
============
负责加载YAML配置文件并提供全局配置访问
"""

import os
from pathlib import Path
from typing import Any, Dict, Optional

import yaml
from loguru import logger


class Config:
    """
    配置管理类
    ----------
    单例模式，全局唯一配置实例
    """

    _instance: Optional["Config"] = None
    _config: Dict[str, Any] = {}

    def __new__(cls, config_path: Optional[str] = None) -> "Config":
        """单例模式实现"""
        if cls._instance is None:
            cls._instance = super().__new__(cls)
            cls._instance._initialized = False
        return cls._instance

    def __init__(self, config_path: Optional[str] = None) -> None:
        """
        初始化配置

        Args:
            config_path: 配置文件路径，默认为 config/config.yaml
        """
        if self._initialized:
            return

        if config_path is None:
            # 默认配置文件路径
            config_path = Path(__file__).parent.parent / "config" / "config.yaml"

        self._load_config(config_path)
        self._apply_env_overrides()
        self._initialized = True

    def _load_config(self, config_path: str | Path) -> None:
        """
        加载YAML配置文件

        Args:
            config_path: 配置文件路径
        """
        config_path = Path(config_path)

        if not config_path.exists():
            logger.warning(f"配置文件不存在: {config_path}，使用默认配置")
            self._config = self._get_default_config()
            return

        with open(config_path, "r", encoding="utf-8") as f:
            self._config = yaml.safe_load(f) or {}

        logger.info(f"已加载配置文件: {config_path}")

    def _apply_env_overrides(self) -> None:
        """
        应用环境变量覆盖配置
        """
        # LLM API Key 从环境变量读取
        if api_key := os.getenv("OPENAI_API_KEY"):
            self._config.setdefault("llm", {})["api_key"] = api_key
            logger.info("已从环境变量加载 OPENAI_API_KEY")

        # LLM Base URL 从环境变量读取
        if base_url := os.getenv("OPENAI_BASE_URL"):
            self._config.setdefault("llm", {})["base_url"] = base_url
            logger.info("已从环境变量加载 OPENAI_BASE_URL")

    def _get_default_config(self) -> Dict[str, Any]:
        """
        获取默认配置

        Returns:
            默认配置字典
        """
        return {
            "llm": {
                "api_key": "",
                "base_url": "http://localhost:8080/v1",
                "model": "Qwen/Qwen2.5-32B",
                "temperature": 0.1,
                "max_tokens": 8192,
                "timeout": 120,
            },
            "concurrency": {
                "max_concurrent": 2,
                "semaphore_timeout": 300,
            },
            "paths": {
                "data_dir": "data",
                "tree_data_dir": "tree_data",
                "category_dir": "tree_data/category",
                "subtrees_dir": "tree_data/subtrees",
                "compressed_dir": "tree_data/compressed",
                "polish_dir": "tree_data/polish",
            },
            "processing": {
                "short_text_threshold": 3000,
                "chunk_size": 2500,
                "chunk_overlap": 200,
                "compression_ratio": 0.3,
                "merge_batch_size": 10,
            },
            "logging": {
                "level": "INFO",
                "format": "<green>{time:YYYY-MM-DD HH:mm:ss}</green> | <level>{level: <8}</level> | <cyan>{name}</cyan>:<cyan>{function}</cyan>:<cyan>{line}</cyan> - <level>{message}</level>",
                "rotation": "10 MB",
                "retention": "7 days",
                "log_file": "logs/pdf_tree.log",
            },
        }

    def get(self, key: str, default: Any = None) -> Any:
        """
        获取配置值，支持点号分隔的嵌套键

        Args:
            key: 配置键，如 "llm.api_key"
            default: 默认值

        Returns:
            配置值
        """
        keys = key.split(".")
        value = self._config

        for k in keys:
            if isinstance(value, dict):
                value = value.get(k)
            else:
                return default

            if value is None:
                return default

        return value

    @property
    def llm(self) -> Dict[str, Any]:
        """LLM配置"""
        return self._config.get("llm", {})

    @property
    def paths(self) -> Dict[str, str]:
        """路径配置"""
        return self._config.get("paths", {})

    @property
    def processing(self) -> Dict[str, Any]:
        """处理配置"""
        return self._config.get("processing", {})

    @property
    def concurrency(self) -> Dict[str, Any]:
        """并发配置"""
        return self._config.get("concurrency", {})

    @property
    def logging_config(self) -> Dict[str, Any]:
        """日志配置"""
        return self._config.get("logging", {})


def get_config(config_path: Optional[str] = None) -> Config:
    """
    获取配置实例的便捷函数

    Args:
        config_path: 配置文件路径

    Returns:
        Config 实例
    """
    return Config(config_path)
